        #region Account balance
        /// <summary>
        /// Get the balance of an account detailed by one or more criteria        
        /// </summary>
        /// <param name="accountNo">Account no</param>
        /// <param name="date">Date the result is calculated to</param>
        /// <param name="objectID">Object id</param>
        /// <param name="objectType">Object type</param>
        /// <param name="currencyID">Currency id</param>
        /// <param name="bankID">Bank id</param>
        /// <param name="locationID">Location id</param>
        /// <param name="branchID">Branch id</param>
        /// <returns>Balance of the account</returns>
        public double GetAccountBalance(
                                string accountNo, 
                                DateTime date, 
                                int? objectID, 
                                string objectType, 
                                int? currencyID, 
                                int? bankID,
                                int? locationID,
                                int? branchID)                                
        {
            ACAccountsController objAccountsController = new ACAccountsController();            
            ACAccountsInfo account = (ACAccountsInfo)objAccountsController.GetObjectByNo(accountNo);
            double balance = 0;
            double initBalance = 0;
            if (account != null)
            {
                string postingRule = account.ACAccountPostingRule;
                if (objectID > 0)
                {
                    account = objAccountsController.GetAccountInitialBalance(accountNo, objectID, objectType, currencyID, bankID);
                    initBalance += account.ACAccountInitialBalance;
                }
                else if (branchID > 0)
                {
                    account = objAccountsController.GetAccountInitialBalance(accountNo, branchID, ObjectType.Branch.ToString(), currencyID, bankID);
                    initBalance += account.ACAccountInitialBalance;
                }
                else if (locationID > 0)
                {
                    BRBranchsController objBranchsController = new BRBranchsController();
                    List<BRBranchsInfo> branches = objBranchsController.GetBranchesByLocationID(locationID.Value);
                    foreach (BRBranchsInfo branch in branches)
                    {
                        account = objAccountsController.GetAccountInitialBalance(accountNo, branch.BRBranchID, ObjectType.Branch.ToString(), currencyID, bankID);
                        initBalance += account.ACAccountInitialBalance;
                    }
                }
                else
                {
                    account = objAccountsController.GetAccountInitialBalance(accountNo, objectID, objectType, currencyID, bankID);
                    initBalance += account.ACAccountInitialBalance;
                }
    
                double debitAmount = GetAccountDebitAmount(accountNo, objectID, objectType, currencyID, bankID, locationID, branchID, null, date);
                double creditAmount = GetAccountCreditAmount(accountNo, objectID, objectType, currencyID, bankID, locationID, branchID, null, date);                
                if (postingRule == AccountPostingRule.IncreasingByDebit.ToString())
                {
                    balance = initBalance + debitAmount - creditAmount;
                }
                else if (postingRule == AccountPostingRule.IncreasingByCredit.ToString())
                {
                    balance = initBalance + creditAmount - debitAmount;
                }
            }
            return balance;            
        }     

